+    align: "center",
+  });
+
+  addFooterSource(slide, theme, "Figure reference: Vaccination innovation timeline (OWID). Data: pathogen identified → vaccine licensed.");
+  addPageNumberBadge(slide, theme, 2);
+  return slide;
+}
+
+if (require.main === module) {
+  const pres = new pptxgen();
+  pres.layout = "LAYOUT_16x9";
+  const theme = {
+    primary: "22223b",
+    secondary: "4a4e69",
+    accent: "9a8c98",
+    light: "c9ada7",
+    bg: "f2e9e4",
+  };
+  createSlide(pres, theme);
+  pres.writeFile({ fileName: "slide-02-preview.pptx" });
+}
+
+module.exports = { createSlide, slideConfig };
+
